    DailyLessonDef(
      id: "course-sec1hum-w35-d4",
      dayNumber: 4,
      titleEn: "Reading: Thura's Timed Practice Reflection",
      titleMy: "စာဖတ်ခြင်း - Thura ၏ Timed Practice Reflection",
